def graph = g.getGraph()
graph.tx().rollback()
def m = graph.openManagement()
['uid','id','gsp_probe_key','expected_count'].each { k ->
    if (m.getPropertyKey(k) == null)
        m.makePropertyKey(k).dataType(Long.class)
         .cardinality(org.janusgraph.core.Cardinality.SINGLE).make()
}
if (m.getPropertyKey('mark') == null)
    m.makePropertyKey('mark').dataType(Boolean.class)
     .cardinality(org.janusgraph.core.Cardinality.SINGLE).make()
if (m.getPropertyKey('_gsp_identity') == null)
    m.makePropertyKey('_gsp_identity').dataType(String.class)
     .cardinality(org.janusgraph.core.Cardinality.SINGLE).make()
['ScorRoot','ScorTarget'].each { label ->
    if (m.getVertexLabel(label) == null) m.makeVertexLabel(label).make()
}
['GSP_SC_HIGH','GSP_SC_REF'].each { label ->
    if (m.getEdgeLabel(label) == null)
        m.makeEdgeLabel(label).multiplicity(org.janusgraph.core.Multiplicity.MULTI).make()
}
if (m.getGraphIndex('gsp_internal_identity') == null)
    m.buildIndex('gsp_internal_identity',org.apache.tinkerpop.gremlin.structure.Vertex.class)
     .addKey(m.getPropertyKey('_gsp_identity')).unique().buildCompositeIndex()
if (m.getGraphIndex('gsp_cost_lookup_ScorRoot_id') == null)
    m.buildIndex('gsp_cost_lookup_ScorRoot_id',org.apache.tinkerpop.gremlin.structure.Vertex.class)
     .addKey(m.getPropertyKey('id')).indexOnly(m.getVertexLabel('ScorRoot')).buildCompositeIndex()
m.commit()
['gsp_internal_identity','gsp_cost_lookup_ScorRoot_id'].each { name ->
    org.janusgraph.graphdb.database.management.ManagementSystem.awaitGraphIndexStatus(graph,name)
      .status(org.janusgraph.core.schema.SchemaStatus.REGISTERED,
              org.janusgraph.core.schema.SchemaStatus.ENABLED)
      .timeout(60,java.time.temporal.ChronoUnit.SECONDS).call()
    def mg = graph.openManagement()
    def index = mg.getGraphIndex(name)
    if (index.getFieldKeys().any { index.getIndexStatus(it) != org.janusgraph.core.schema.SchemaStatus.ENABLED })
        mg.updateIndex(index,org.janusgraph.core.schema.SchemaAction.ENABLE_INDEX).get()
    mg.commit()
}

g.addV('ScorRoot').property('_gsp_identity','ScorRoot:1')
 .property('uid',1L).property('id',1L).property('gsp_probe_key',1L)
 .property('expected_count',40000L).iterate()
graph.tx().commit()
(1..40000).each { i ->
    def uid = 680487L + i
    g.addV('ScorTarget').property('_gsp_identity','ScorTarget:'+uid)
     .property('uid',uid).property('mark',true).property('gsp_probe_key',1L).iterate()
    if (i % 250 == 0) graph.tx().commit()
}
(2L..4L).each { uid ->
    g.addV('ScorTarget').property('_gsp_identity','ScorTarget:'+uid)
     .property('uid',uid).property('mark',true).property('gsp_probe_key',1L).iterate()
}
graph.tx().commit()
(1..40000).each { i ->
    def root = g.V().has('_gsp_identity','ScorRoot:1').next()
    def target = g.V().has('_gsp_identity','ScorTarget:'+(680487L+i)).next()
    root.addEdge('GSP_SC_HIGH',target)
    if (i % 250 == 0) graph.tx().commit()
}
(2L..4L).each { uid ->
    g.V().has('_gsp_identity','ScorRoot:1').next()
     .addEdge('GSP_SC_REF',g.V().has('_gsp_identity','ScorTarget:'+uid).next())
}
graph.tx().commit()
